async function syncTeamSnap(env,{full=true}={}){const cfg=await appConfig(env);if(!cfg?.teamsnap_token_enc)throw new ApiError('Connect TeamSnap from /admin first.',409,'teamsnap_not_configured');const token=await decryptSecret(env,cfg.teamsnap_token_enc),started=now();await env.DB.prepare(`UPDATE app_config SET sync_status='syncing',sync_error=NULL,updated_at=? WHERE id=?`).bind(started,APP_ID).run();try{const mePayload=await tsJson(`${TEAMSNAP_API}/me`,token),me=tsCollectionObjects(mePayload)[0]||{};if(me.id==null)throw new ApiError('TeamSnap did not return an account identity.',502,'teamsnap_identity_missing');let searched=[],related=[];try{searched=await tsFetchCollection('teams/search',{user_id:me.id},token);}catch{}const rel=await Promise.allSettled(discoverTsTeamUrls(mePayload,me).map(u=>tsFetchCollection(u,{},token)));for(const r of rel)if(r.status==='fulfilled')related.push(...r.value);const map=new Map();for(const t of [...searched,...related])if(t?.id!=null)map.set(String(t.id),{...(map.get(String(t.id))||{}),...t});const saved=await env.DB.prepare('SELECT data_json FROM app_teams').all();for(const r of saved.results||[]){const t=safeJsonParse(r.data_json,{});if(t?.id!=null&&serverTeamArchived(t)&&!map.has(String(t.id)))map.set(String(t.id),t);}const teams=[...map.values()];if(!teams.length)throw new ApiError('No TeamSnap teams are available for this account.',409,'teamsnap_no_teams');const stamp=now();await env.DB.prepare('DELETE FROM app_teams').run();for(const t of teams){const dataset=await ensureDataset(env,t);await env.DB.prepare(`INSERT INTO app_teams(team_id,dataset_id,data_json,updated_at) VALUES(?,?,?,?)`).bind(String(t.id),dataset.dataset_id,JSON.stringify(sanitizeTeam(t)),stamp).run();}const targetTeams=full?teams:teams.filter(t=>!serverTeamArchived(t));let failures=0;for(let i=0;i<targetTeams.length;i+=3){const batch=targetTeams.slice(i,i+3);await Promise.all(batch.map(async team=>{const resources=['events','members','locations','opponents','availabilities'],results=await Promise.allSettled(resources.map(r=>tsFetchCollection(`${r}/search`,{team_id:team.id,...(r==='events'?{sort_start_date:'asc'}:{})},token)));for(let j=0;j<resources.length;j++){const r=results[j];if(r.status==='fulfilled')await saveTeamResource(env,team,resources[j],r.value,stamp);else failures++;}}));}const status=failures?'partial':'ready',error=failures?`${failures} TeamSnap resource update${failures===1?'':'s'} failed; previously saved data was kept where available.`:null;await env.DB.prepare(`UPDATE app_config SET teamsnap_user_id=?,last_sync_at=?,updated_at=?,sync_status=?,sync_error=? WHERE id=?`).bind(String(me.id),stamp,stamp,status,error,APP_ID).run();return{ok:true,teams:teams.length,sync_status:status,sync_error:error,last_sync_at:stamp};}catch(e){await env.DB.prepare(`UPDATE app_config SET sync_status='error',sync_error=?,updated_at=? WHERE id=?`).bind(clean(e?.message)||'TeamSnap sync failed.',now(),APP_ID).run();throw e;}}
async function connectTeamSnap(request,env){await requireAdmin(request,env);const b=await bodyJson(request),token=clean(b.access_token),clientId=clean(b.client_id);if(!token)throw new ApiError('TeamSnap did not return an access token.',400,'teamsnap_token_missing');const mePayload=await tsJson(`${TEAMSNAP_API}/me`,token),me=tsCollectionObjects(mePayload)[0]||{};if(me.id==null)throw new ApiError('TeamSnap connection could not be verified.',401,'teamsnap_auth_required');const prior=await appConfig(env),enc=await encryptSecret(env,token),t=now();await env.DB.prepare(`INSERT INTO app_config(id,teamsnap_token_enc,teamsnap_client_id,teamsnap_user_id,include_preseason,connected_at,updated_at,sync_status,sync_error) VALUES(?,?,?,?,?,?,?,?,NULL) ON CONFLICT(id) DO UPDATE SET teamsnap_token_enc=excluded.teamsnap_token_enc,teamsnap_client_id=excluded.teamsnap_client_id,teamsnap_user_id=excluded.teamsnap_user_id,updated_at=excluded.updated_at,sync_status='connected',sync_error=NULL`).bind(APP_ID,enc,clientId,String(me.id),Number(prior?.include_preseason||0),prior?.connected_at||t,t,'connected').run();const result=await syncTeamSnap(env);return json({...result,viewer_urls:await datasetLinks(request,env)});}
async function publicBootstrap(env,access){const cfg=await appConfig(env),q=access?.admin?env.DB.prepare('SELECT data_json FROM app_teams ORDER BY team_id'):env.DB.prepare('SELECT data_json FROM app_teams WHERE dataset_id=? ORDER BY team_id').bind(access.dataset_id),result=await q.all(),teams=(result.results||[]).map(r=>safeJsonParse(r.data_json,{})).filter(t=>t?.id!=null);return json({configured:!!cfg?.teamsnap_token_enc&&teams.length>0,teams,last_sync_at:cfg?.last_sync_at||null,sync_status:cfg?.sync_status||'not_configured',sync_error:cfg?.sync_error||null,settings:{include_preseason:!!Number(cfg?.include_preseason||0)},dataset:access?.admin?null:{family_key:access?.family_key||null,display_name:access?.display_name||null},version:APP_VERSION});}
