async function traceProfileCandidates(env,conn,cookie,token,userId){
  const uid=Number(userId||token?.user_id);
  if(!Number.isFinite(uid))throw new ApiError('Trace profile identity is unavailable.',502,'trace_profile_identity_missing');

  let relations=[];
  try{
    const d=await traceLapiGraphql(cookie,'getUserRelations',USER_RELATIONS_QUERY,{to_user_id:uid,token,include_self:true});
    relations=Array.isArray(d?.userRelations)?d.userRelations:[];
  }catch{}

  const pr=await env.DB.prepare('SELECT user_id,name,jersey FROM trace_players WHERE teamsnap_key=?').bind(conn.teamsnap_key).all(),
        teamPlayers=pr.results||[],teamIds=new Set(teamPlayers.map(p=>String(p.user_id))),
        fp=safeJsonParse(conn.fingerprint_json,{}),current=Array.isArray(fp.players)?fp.players:[];

  const playerScore=p=>{
    let best=0;
    for(const q of current){
      let s=nameScore(p?.name,q?.name),j=clean(p?.jersey),qj=clean(q?.jersey);
      if(j&&qj&&j===qj)s=Math.max(s,98);
      if(s>best)best=s;
    }
    return best;
  };

  const ordered=[],seen=new Set(),push=(id,source,score=0,relation='')=>{
    const s=String(id||'');if(!/^\d+$/.test(s)||seen.has(s))return;
    seen.add(s);ordered.push({user_id:Number(s),source,score,relation});
  };

  // Strongest evidence: authenticated relations that are actual players on this connected team.
  for(const r of relations){
    const id=r?.user_id??r?.user?.user_id;
    if(teamIds.has(String(id)))push(id,'account_relation_team_player',300,clean(r?.relation));
  }
  // Then current TeamSnap-roster matches from the Trace roster.
  for(const p of [...teamPlayers].sort((a,b)=>playerScore(b)-playerScore(a))){
    const score=playerScore(p);
    if(score>=70)push(p.user_id,'current_team_player',200+score);
  }
  // Then other authenticated relations, including self/spouse/children.
  for(const r of relations)push(r?.user_id??r?.user?.user_id,'account_relation',120,clean(r?.relation));
  push(uid,'signed_in_account',100,'self');
  // Final generic fallback: a small sample of team athlete profiles.
  for(const p of [...teamPlayers].sort((a,b)=>playerScore(b)-playerScore(a)).slice(0,12))
    push(p.user_id,'team_player_fallback',playerScore(p));

  const out=[];
  for(const c of ordered){
    try{
      const d=await traceLapiGraphql(cookie,'findProfileByUserId',PROFILE_BY_USER_QUERY,{user_id:c.user_id,token}),
            hash=clean(d?.profile?.hash_key);
      if(slugOk(hash))out.push({...c,hash,name:clean(d?.profile?.name)});
    }catch{}
  }
  return out;
}
async function traceAccessProfile(env,conn,cookie,token,userId,probeGameId){
  let meta=safeJsonParse(conn.meta_json,{});
  const cachedHash=clean(meta.trace_profile_hash);
  if(meta.trace_profile_access_version===TRACE_PROFILE_ACCESS_VERSION&&slugOk(cachedHash)){
    try{
      const raw=await traceRichGame(cookie,token,cachedHash,probeGameId),game=targetGameAsHome(raw,conn);
      if(richGameUsable(game))return{hash:cachedHash,user_id:meta.trace_profile_user_id||null,source:meta.trace_profile_source||'cached_team_access',probeGame:raw};
    }catch{}
  }

  const candidates=await traceProfileCandidates(env,conn,cookie,token,userId),attempts=[];
  for(const c of candidates){
    try{
      const raw=await traceRichGame(cookie,token,c.hash,probeGameId),game=targetGameAsHome(raw,conn),
            moments=Array.isArray(game?.moments)?game.moments.length:0,members=Array.isArray(game?.team_members)?game.team_members.length:0;
      attempts.push({source:c.source,user_id:c.user_id,moments,members});
      if(!richGameUsable(game))continue;

      meta=safeJsonParse((await connection(env,conn.teamsnap_key))?.meta_json||conn.meta_json,{});
      meta.trace_profile_hash=c.hash;
      meta.trace_profile_user_id=c.user_id;
      meta.trace_profile_source=c.source;
      meta.trace_profile_relation=c.relation||null;
      meta.trace_profile_access_version=TRACE_PROFILE_ACCESS_VERSION;
      meta.trace_profile_verified_game=String(probeGameId);
      meta.trace_profile_verified_at=now();
      await env.DB.prepare('UPDATE trace_connections SET meta_json=?,updated_at=? WHERE teamsnap_key=?')
        .bind(JSON.stringify(meta),now(),conn.teamsnap_key).run();
      return{hash:c.hash,user_id:c.user_id,source:c.source,probeGame:raw};
    }catch(e){
      attempts.push({source:c.source,user_id:c.user_id,error:clean(e?.message||e).slice(0,160)});
    }
  }

  const summary=attempts.slice(0,6).map(a=>`${a.source}:${a.moments??'-'}m/${a.members??'-'}p`).join(', ');
  throw new ApiError(`Trace could not resolve a team-access athlete profile for game ${probeGameId}${summary?` (${summary})`:''}.`,502,'trace_profile_access_missing');
}
