        await env.DB.prepare(`INSERT INTO trace_game_rows(teamsnap_key,game_id,game_date,opponent,rows_json,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(teamsnap_key,game_id) DO UPDATE SET game_date=excluded.game_date,opponent=excluded.opponent,rows_json=excluded.rows_json,updated_at=excluded.updated_at`).bind(key,String(g.game_id),gameDate,opponent,JSON.stringify(calc.rows),t).run();
        await env.DB.prepare(`INSERT INTO trace_calculations(teamsnap_key,game_id,engine_version,source_hash,rows_json,quality_json,calculated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(teamsnap_key,game_id,engine_version,source_hash) DO UPDATE SET rows_json=excluded.rows_json,quality_json=excluded.quality_json,calculated_at=excluded.calculated_at`).bind(key,String(g.game_id),RADAR_ENGINE_VERSION,sourceHash,JSON.stringify(calc.rows),JSON.stringify(calc.built?.quality||{}),t).run();
        await env.DB.prepare(`UPDATE trace_games SET playing_status='ready',playing_error=NULL,playing_updated_at=?,playing_version=? WHERE teamsnap_key=? AND game_id=?`).bind(t,RADAR_ENGINE_VERSION,key,g.game_id).run();
        const currentConn=await connection(env,key),meta=safeJsonParse(currentConn?.meta_json,{});
