  const result=teamId?await env.DB.prepare(`SELECT g.game_id,g.game_date,g.opponent,g.playing_status,g.playing_version,r.source_status,r.source_hash,r.expected_halves,r.total_bytes,r.first_fetched_at,r.completed_at,r.updated_at AS raw_updated_at FROM trace_games g LEFT JOIN trace_raw_sources r ON r.teamsnap_key=g.teamsnap_key AND r.game_id=g.game_id AND r.trace_team_id=? WHERE g.teamsnap_key=? ORDER BY COALESCE(g.game_date,g.updated_at) DESC,CAST(g.game_id AS INTEGER) DESC`).bind(teamId,key).all():{results:[]};
  return{ok:true,archive_version:RAW_ARCHIVE_VERSION,engine_version:RADAR_ENGINE_VERSION,trace_team_id:teamId,stats,games:result.results||[]};
